#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
RAW_DIR="$ROOT_DIR/.tmp-raw-images"
OUT_DIR="$ROOT_DIR/public/images"

rm -rf "$RAW_DIR" "$OUT_DIR"
mkdir -p "$RAW_DIR" "$OUT_DIR"

download_and_convert() {
  local name="$1"
  local url="$2"
  local crop_top="${3:-0}"
  local crop_bottom="${4:-0}"

  local raw_file="$RAW_DIR/${name}.img"
  local jpg_tmp="$RAW_DIR/${name}.jpg"
  local out_jpg="$OUT_DIR/${name}.jpg"
  local out_webp="$OUT_DIR/${name}.webp"

  echo "Downloading $name..."
  curl -fsSL -A "Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)" "$url" -o "$raw_file"
  sips -s format jpeg "$raw_file" --out "$jpg_tmp" >/dev/null

  if [[ "$crop_top" -gt 0 || "$crop_bottom" -gt 0 ]]; then
    local w h off_y target_h
    w=$(sips -g pixelWidth "$jpg_tmp" | awk '/pixelWidth/{print $2}')
    h=$(sips -g pixelHeight "$jpg_tmp" | awk '/pixelHeight/{print $2}')
    off_y=$(( h * crop_top / 100 ))
    target_h=$(( h * (100 - crop_top - crop_bottom) / 100 ))
    echo "Cropping $name from ${w}x${h} (offsetY=${off_y}, targetH=${target_h})..."
    sips --cropOffset "$off_y" 0 -c "$target_h" "$w" "$jpg_tmp" --out "$jpg_tmp" >/dev/null
  fi

  sips -Z 1440 -s format jpeg -s formatOptions 84 "$jpg_tmp" --out "$out_jpg" >/dev/null
  cwebp -quiet -q 82 "$out_jpg" -o "$out_webp"
}

